/**
 * Removes the `R` type parameter from `createRequestFunction` in a
 * `common.ts` generated by the typescript-axios generator, and annotates its
 * return type as `Promise<AxiosResponse<T>>`.
 *
 * `AxiosInstance.request<T, R>` returns a conditional type built on an
 * unexported `unique symbol`. While `R` is generic, that type is not
 * assignable to `Promise<R>`, and TypeScript cannot emit a declaration for it
 * (TS2527). With `R` left at its default, it resolves to `AxiosResponse<T>`.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const replacements = [
  {
    stock:
      "<T = unknown, R = AxiosResponse<T>>(axios: AxiosInstance = globalAxios, basePath: string = BASE_PATH) => {",
    patched:
      "<T = unknown>(axios: AxiosInstance = globalAxios, basePath: string = BASE_PATH): Promise<AxiosResponse<T>> => {",
  },
  {
    stock: "return axios.request<T, R>(axiosRequestArgs);",
    patched: "return axios.request<T>(axiosRequestArgs);",
  },
];

const filePath = resolve(process.argv[2] ?? "common.ts");
let source = readFileSync(filePath, "utf-8");

/**
 * @param {string} text
 * @param {string} search
 */
const countOccurrences = (text, search) => text.split(search).length - 1;

for (const { stock, patched } of replacements) {
  const stockCount = countOccurrences(source, stock);
  const patchedCount = countOccurrences(source, patched);

  if (stockCount === 0 && patchedCount === 1) {
    continue;
  }

  if (stockCount !== 1 || patchedCount !== 0) {
    console.error(
      `patch-request-function: expected \`${stock}\` exactly once in ${filePath}, found it ${stockCount} times (and the patched form ${patchedCount} times)`,
    );
    process.exit(1);
  }

  source = source.replace(stock, patched);
}

writeFileSync(filePath, source);
